braid-provisional-excluded:
.input {$n :number}
.match $n
one {{Left out: {$n} provisional reading.}}
* {{Left out: {$n} provisional readings.}}

overview-provisional-excluded:
.input {$n :number}
.match $n
one {{{$n} provisional value was left out of this confirmed range.}}
* {{{$n} provisional values were left out of this confirmed range.}}

spark-provisional-excluded:
.input {$n :number}
.match $n
one {{Left out: {$n} provisional reading.}}
* {{Left out: {$n} provisional readings.}}

prov-readings:
.input {$n :number}
.match $n
one {{This observation is based on {$n} reading.}}
* {{This observation is based on {$n} readings.}}

history-all-provisional:
.input {$n :number}
.match $n
one {{The only reading is provisional. Use this as a rough summary.}}
* {{All {$n} readings are provisional. Use this as a rough summary.}}

