aa-count:
.input {$n :number}
.match $n
one {{{$n} alert was published as of {$time}.}}
* {{{$n} alerts were published as of {$time}.}}

settings-has:
.input {$n :number}
.match $n
one {{This device stores {$n} alert plus your language, units, and display choices.}}
* {{This device stores {$n} alerts plus your language, units, and display choices.}}
